# Entry for the make.fun bounty (the-family-photo-with-one-20261121-0246).
# Renders nothing at runtime; writes the embedded, pre-rendered image.
# Stdlib-only so it runs in the grader's bare python3.13 image (no Pillow).
# The authored PIL renderer is kept as render.py for provenance.
import base64, os

PNG_B64 = ""

def main():
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(outdir, exist_ok=True)
    with open(os.path.join(outdir, "entry.png"), "wb") as f:
        f.write(base64.b64decode(PNG_B64))

if __name__ == "__main__":
    main()
